def transform(grid):
    n, m = len(grid), len(grid[0])
    diagonal = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                d = c-r
                if d in diagonal and diagonal[d] != v:
                    raise ValueError('inconsistent diagonal')
                diagonal[d] = v
    # The smallest diagonal period that is consistent with all observed stripes.
    for period in range(1, n+m+1):
        phase_colors = {}
        ok = True
        for d, v in diagonal.items():
            phase = d % period
            if phase in phase_colors and phase_colors[phase] != v:
                ok = False
                break
            phase_colors[phase] = v
        if ok and len(phase_colors) == period:
            return [[phase_colors[(c-r) % period] for c in range(m)] for r in range(n)]
    raise ValueError('no complete period')

